async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kalahari = ee.Geometry.Point(22.0, -23.5); // A point within the Kalahari Desert

  // Date ranges for comparison (with a buffer for cloud-free images)
  const date2009_start = '2009-04-04'; // April 19, 2009 +/- 15 days
  const date2009_end = '2009-05-04';

  const date2008_start = '2008-07-22'; // August 6, 2008 +/- 15 days
  const date2008_end = '2008-08-21';

  // Scale for reduceRegion (to avoid timeout, use a reasonable scale for regional analysis)
  const scale = 1000;

  // Function to mask clouds and calculate NDVI for Landsat 5 TM
  function maskCloudsAndCalculateNDVI(image) {
    // Get the pixel QA band.
    const qa = image.select('pixel_qa');

    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);

    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                  .and(qa.bitwiseAnd(cloudsBitMask).eq(0));

    // Apply the mask and select relevant bands.
    const maskedImage = image.updateMask(mask).select(['B3', 'B4']);

    // Calculate NDVI
    const ndvi = maskedImage.normalizedDifference(['B4', 'B3']).rename('NDVI');

    return image.addBands(ndvi);
  }

  // 2. Data Acquisition & Check for 2009
  let collection2009 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterBounds(kalahari)
    .filterDate(date2009_start, date2009_end);

  const size2009 = await collection2009.size().getInfo();
  if (size2009 === 0) {
    console.log(`2009 Images: ${size2009}`);
    console.log("C1");
    return;
  }
  console.log(`2009 Images (initial): ${size2009}`);

  // Process 2009 collection
  collection2009 = collection2009.map(maskCloudsAndCalculateNDVI)
                                 .select('NDVI'); // Select only the NDVI band

  // Get median image for the period
  const image2009 = collection2009.median();

  // 3. Data Acquisition & Check for 2008
  let collection2008 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterBounds(kalahari)
    .filterDate(date2008_start, date2008_end);

  const size2008 = await collection2008.size().getInfo();
  if (size2008 === 0) {
    console.log(`2008 Images: ${size2008}`);
    console.log("C1");
    return;
  }
  console.log(`2008 Images (initial): ${size2008}`);

  // Process 2008 collection
  collection2008 = collection2008.map(maskCloudsAndCalculateNDVI)
                                 .select('NDVI'); // Select only the NDVI band

  // Get median image for the period
  const image2008 = collection2008.median();

  // 4. Calculation
  // Reduce regions for 2009
  const stats2009 = await image2009.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: kalahari,
    scale: scale,
    maxPixels: 1e9,
  }).getInfo();

  const ndvi2009 = stats2009 ? stats2009.NDVI : null;
  const count2009 = stats2009 ? stats2009.NDVI_count : 0;

  // Reduce regions for 2008
  const stats2008 = await image2008.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: kalahari,
    scale: scale,
    maxPixels: 1e9,
  }).getInfo();

  const ndvi2008 = stats2008 ? stats2008.NDVI : null;
  const count2008 = stats2008 ? stats2008.NDVI_count : 0;

  // 5. Validation & Final Answer
  if (count2009 === 0 || count2008 === 0) {
    console.log(`2009 Valid Pixels: ${count2009}`);
    console.log(`2008 Valid Pixels: ${count2008}`);
