    console.log(`2009 NDVI: ${ndvi2009}, Pixels: ${count2009}`);
    console.log(`2008 NDVI: ${ndvi2008}, Pixels: ${count2008}`);
    console.log("C3"); // Calculation failed or invalid result
    return;
  }

  console.log(`2009 NDVI: ${ndvi2009.toFixed(3)}, Pixels: ${count2009}`);
  console.log(`2008 NDVI: ${ndvi2008.toFixed(3)}, Pixels: ${count2008}`);

